def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target-x in seen: return [seen[target-x], i]
        seen[x] = i
    return None

from collections import deque
def bfs(graph, start):
    dist = {start: 0}; q = deque([start])
    while q:
        u = q.popleft()
        for v in graph[u]:
            if v not in dist:
                dist[v] = dist[u]+1; q.append(v)
    return dist

def layer_norm(x, gamma, beta, eps=1e-5):
    mu = x.mean(axis=-1, keepdims=True)
    var = ((x-mu)**2).mean(axis=-1, keepdims=True)
    return (x-mu)/np.sqrt(var+eps)*gamma+beta

from math import exp, log, ceil

def hoeffding_bound(n, epsilon, candidates=1):
    if n <= 0 or epsilon <= 0 or candidates < 1:
        raise ValueError("positive n/epsilon and at least one candidate required")
    return min(1.0, 2 * candidates * exp(-2*n*epsilon**2))

def required_samples(epsilon, delta, candidates=1):
    if epsilon <= 0 or not 0 < delta < 1 or candidates < 1:
        raise ValueError("invalid precision, failure probability, or candidate count")
    return ceil(log(2*candidates/delta)/(2*epsilon**2))

