from statistics import NormalDist
normal = NormalDist()

def per_arm_size(delta, sigma, alpha=.05, power=.80):
    if delta <= 0 or sigma <= 0 or not 0 < alpha < 1 or not .5 < power < 1:
        raise ValueError("invalid planning parameters")
    zcrit = normal.inv_cdf(1-alpha/2)
    zpower = normal.inv_cdf(power)
    return ceil(2*sigma**2*(zcrit+zpower)**2/delta**2)

def approximate_power(n, delta, sigma, alpha=.05):
    zcrit = normal.inv_cdf(1-alpha/2)
    shift = delta/(sigma*sqrt(2/n))
    return 1-normal.cdf(zcrit-shift)+normal.cdf(-zcrit-shift)

n = per_arm_size(delta=1, sigma=2)
assert n == 63
