import unicodedata

def canonical(text):
    # Minimal declared policy: Unicode normalization and whitespace collapse.
    return " ".join(unicodedata.normalize("NFKC", text).split())

def fingerprint(text):
    return hashlib.sha256(canonical(text).encode("utf-8")).hexdigest()

