import numpy as np
def noisy_sample(x0, alpha_bar, rng):
    x0 = np.asarray(x0, dtype=float)
    if not 0 < alpha_bar <= 1:
        raise ValueError("alpha_bar must lie in (0, 1]")
    eps = rng.normal(size=x0.shape)
    xt = np.sqrt(alpha_bar)*x0 + np.sqrt(1-alpha_bar)*eps
    return xt, eps
def estimate_clean(xt, predicted_noise, alpha_bar):
    if not 0 < alpha_bar <= 1:
        raise ValueError("alpha_bar must lie in (0, 1]")
    return (xt-np.sqrt(1-alpha_bar)*predicted_noise)/np.sqrt(alpha_bar)
rng = np.random.default_rng(0)
x0 = np.array([1.0, -2.0])
xt, eps = noisy_sample(x0, 0.25, rng)
assert np.allclose(estimate_clean(xt, eps, 0.25), x0)

import numpy as np
def ctc_log_probability(log_probs, labels, blank=0):
    # Small reference implementation; log_probs has shape [time, classes].
    lp = np.asarray(log_probs, dtype=float)
    labels = list(labels)
    if lp.ndim != 2 or blank in labels:
        raise ValueError("invalid emissions or blank in target")
    T, classes = lp.shape
    if not 0 <= blank < classes or any(y < 0 or y >= classes for y in labels):
        raise ValueError("invalid label index")
    if T == 0:
        return 0.0 if not labels else -np.inf
    z = [blank]
    for y in labels:
        z.extend([y, blank])
    prev = np.full(len(z), -np.inf)
    prev[0] = lp[0, blank]
    if labels:
        prev[1] = lp[0, z[1]]
    for t in range(1, T):
        cur = np.full(len(z), -np.inf)
        for s, label in enumerate(z):
            incoming = [prev[s]]
            if s >= 1:
                incoming.append(prev[s-1])
            if s >= 2 and label != blank and label != z[s-2]:
                incoming.append(prev[s-2])
            cur[s] = np.logaddexp.reduce(incoming) + lp[t, label]
        prev = cur
    return prev[0] if not labels else np.logaddexp(prev[-1], prev[-2])
lp = np.log(np.array([[0.4, 0.6], [0.4, 0.6]]))
assert np.isclose(np.exp(ctc_log_probability(lp, [1])), 0.84)
assert np.isneginf(ctc_log_probability(lp, [1, 1]))

class DSU:
    def __init__(self, n):
        if n < 0:
            raise ValueError('n must be nonnegative')
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n
    def find(self, x):
        if not 0 <= x < len(self.parent):
            raise IndexError(x)
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, a, b):
        a, b = self.find(a), self.find(b)
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = b, a
        self.parent[b] = a
        self.size[a] += self.size[b]
        self.components -= 1
        return True

u = DSU(5)
assert u.union(0, 1) and u.union(1, 2)
assert not u.union(2, 0)
assert u.components == 3
assert u.size[u.find(2)] == 3
assert u.find(0) != u.find(4)

def knapsack(items, capacity):
    # Positive integer weights; selecting nothing is allowed.
    if capacity < 0 or any(w <= 0 for w, _ in items):
        raise ValueError('invalid capacity or weight')
    best = [0] * (capacity + 1)
    for weight, value in items:
        for c in range(capacity, weight - 1, -1):
            best[c] = max(best[c], best[c - weight] + value)
    return best[capacity]

assert knapsack([(2, 3), (3, 4), (4, 5)], 5) == 7
assert knapsack([(2, 3)], 4) == 3  # not 6: one copy only
assert knapsack([], 9) == 0
assert knapsack([(1, -5)], 3) == 0

def correlate(x, k):
    h, w = len(x), len(x[0])
    kh, kw = len(k), len(k[0])
    if kh > h or kw > w:
        raise ValueError('kernel must fit')
    return [[sum(x[i+a][j+b]*k[a][b]
                 for a in range(kh) for b in range(kw))
             for j in range(w-kw+1)] for i in range(h-kh+1)]

def backward(x, k, g):
    dx = [[0.0]*len(x[0]) for _ in x]
    dk = [[0.0]*len(k[0]) for _ in k]
    for i in range(len(g)):
        for j in range(len(g[0])):
            for a in range(len(k)):
                for b in range(len(k[0])):
                    dx[i+a][j+b] += g[i][j]*k[a][b]
                    dk[a][b] += g[i][j]*x[i+a][j+b]
    return dx, dk

